//! The procedural date functions against PHP 8.5.13 with a faked clock (`tests/vectors/functions.json`,
//! generated by `functions.gen.php`; regenerate with `crates/twig-date/tests/vectors/regen.sh functions`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, classes, functions};
use twig_value::Value;

fn set_default(c: &Ctx, z: &str) {
    assert!(
        c.ctx
            .default_timezone_set(z.as_bytes(), &mut Vec::new())
            .unwrap()
    );
}

#[test]
fn mktime_and_checkdate() {
    let v = load("functions");
    let c = Ctx::new();
    let mut r = Report::new("mktime()/checkdate()");
    for case in v["mktime"].as_array().unwrap() {
        let gmt = case[0].as_bool().unwrap();
        set_default(&c, s(&case[1]));
        c.now(i(&case[2]), 0);
        let a: Vec<Option<i64>> = case[3]
            .as_array()
            .unwrap()
            .iter()
            .map(Json::as_i64)
            .collect();
        let arg = |k: usize| a.get(k).copied().flatten();
        let got = functions::php_mktime(
            &c.ctx,
            gmt,
            a[0].unwrap(),
            arg(1),
            arg(2),
            arg(3),
            arg(4),
            arg(5),
        )
        .unwrap();
        r.eq(Json::from(got), case[4].clone(), || format!("{case}"));
    }
    for case in v["checkdate"].as_array().unwrap() {
        let got = functions::checkdate(i(&case[0]), i(&case[1]), i(&case[2]));
        r.eq(Json::Bool(got), case[3].clone(), || format!("{case}"));
    }
    r.finish();
}

#[test]
fn strtotime() {
    let v = load("functions");
    let c = Ctx::new();
    let mut r = Report::new("strtotime()");
    for case in v["strtotime"].as_array().unwrap() {
        set_default(&c, s(&case[0]));
        c.now(i(&case[1]), 0);
        let got = functions::strtotime(&c.ctx, &bytes(&case[2]), case[3].as_i64()).unwrap();
        r.eq(
            got.map_or(Json::Bool(false), Json::from),
            case[4].clone(),
            || format!("{case}"),
        );
    }
    r.finish();
}

#[test]
fn idate_getdate_localtime() {
    let v = load("functions");
    let c = Ctx::new();
    let mut r = Report::new("idate()/getdate()/localtime()");
    for case in v["idate"].as_array().unwrap() {
        set_default(&c, s(&case[0]));
        let mut diags = Vec::new();
        let got = functions::idate(
            &c.ctx,
            s(&case[2]).as_bytes(),
            Some(i(&case[1])),
            &mut diags,
        )
        .unwrap();
        r.eq(to_json(&got), case[3].clone(), || format!("{case}"));
        r.eq(Json::from(diag_strings(&diags)), case[4].clone(), || {
            format!("diagnostics {case}")
        });
    }
    for case in v["getdate"].as_array().unwrap() {
        set_default(&c, s(&case[0]));
        let ts = Some(i(&case[1]));
        let g = functions::getdate(&c.ctx, ts).unwrap();
        r.eq(to_json(&Value::Array(g)), case[2].clone(), || {
            format!("getdate {case}")
        });
        let l = functions::localtime(&c.ctx, ts, false).unwrap();
        r.eq(to_json(&Value::Array(l)), case[3].clone(), || {
            format!("localtime {case}")
        });
        let l = functions::localtime(&c.ctx, ts, true).unwrap();
        r.eq(to_json(&Value::Array(l)), case[4].clone(), || {
            format!("localtime assoc {case}")
        });
    }
    r.finish();
}

#[test]
fn date_parse() {
    let v = load("functions");
    let c = Ctx::new();
    let mut r = Report::new("date_parse()/date_parse_from_format()");
    for case in v["parse"].as_array().unwrap() {
        let got = functions::date_parse(&c.ctx, &bytes(&case[0]));
        r.eq(to_json(&Value::Array(got)), case[1].clone(), || {
            format!("{case}")
        });
    }
    for case in v["parse_from_format"].as_array().unwrap() {
        let got =
            match functions::date_parse_from_format(&c.ctx, &bytes(&case[0]), &bytes(&case[1])) {
                Ok(a) => to_json(&Value::Array(a)),
                Err(e) => Json::String(exc(&e)),
            };
        r.eq(got, case[2].clone(), || format!("{case}"));
    }
    r.finish();
}

#[test]
fn default_timezone_and_now() {
    let v = load("functions");
    let c = Ctx::new();
    let mut r = Report::new("date_default_timezone_set()/now");
    set_default(&c, "UTC");
    for case in v["default_tz"].as_array().unwrap() {
        let mut diags = Vec::new();
        let ok =
            functions::date_default_timezone_set(&c.ctx, &bytes(&case[0]), &mut diags).unwrap();
        r.eq(Json::Bool(ok), case[1].clone(), || format!("{case}"));
        let got = functions::date_default_timezone_get(&c.ctx).unwrap();
        r.eq(Json::String(got), case[2].clone(), || format!("get {case}"));
        r.eq(Json::from(diag_strings(&diags)), case[3].clone(), || {
            format!("diagnostics {case}")
        });
    }
    set_default(&c, "Europe/Vilnius");
    for case in v["now"].as_array().unwrap() {
        c.now(i(&case[0]), i(&case[1]));
        let mut diags = Vec::new();
        let d = DateObject::construct(&c.ctx, classes::datetime(), b"", None).unwrap();
        let got = Json::from(vec![
            case[0].clone(),
            case[1].clone(),
            Json::from(functions::time(&c.ctx)),
            Json::String(enc(functions::date(&c.ctx, b"c", None).unwrap().as_bytes())),
            Json::from(functions::mktime(&c.ctx, 0, None, None, None, None, None).unwrap()),
            functions::strtotime(&c.ctx, b"now", None)
                .unwrap()
                .map_or(Json::Bool(false), Json::from),
            to_json(&functions::idate(&c.ctx, b"U", None, &mut diags).unwrap()),
            Json::String(enc(functions::date(&c.ctx, b"Y-m-d", None)
                .unwrap()
                .as_bytes())),
            Json::String(str_val(
                &call(&d, "format", vec![php_str("U.u")], &mut diags).unwrap(),
            )),
        ]);
        r.eq(got, Json::Array(case.as_array().unwrap().clone()), || {
            format!("{case}")
        });
    }
    r.eq(
        Json::from(functions::timezone_version_get(&c.ctx)),
        v["version"].clone(),
        || "timezone_version_get()".to_owned(),
    );
    r.finish();
}
